98	/// End-to-end coverage for Story 2.4's biometric toggle plus spec-8-3's
99	/// profile-name editing, driven through the real production object graph
100	/// `sl` resolves for `AccountSettingsScreen`/`app_router.dart` — the real
101	/// `AccountSettingsRepositoryImpl` through `AccountRemoteDataSource`,
102	/// `ApiClient` and `Dio` (both real interceptors attached) down to this
103	/// faked transport boundary only. No device/simulator/CI exists yet
104	/// (AGENTS.md).
105	///
106	/// Complements rather than duplicates existing coverage:
107	/// `account_settings_repository_impl_test.dart` already proves every I/O-
108	/// matrix transition (including the generation guards) against a *mocked*
109	/// `AccountRemoteDataSource` (no real URL building, headers, retry policy
110	/// or DTO decoding involved), and `account_remote_data_source_test.dart`
111	/// proves the DTO mapping against a *mocked* `ApiClient`. Neither drives a
112	/// real `account-settings-update` round trip — real URL building, real
113	/// headers, the real `RetryInterceptor` policy, the real
114	/// `AccountSettingsDto.fromJson()` mapping off a real decoded JSON payload
115	/// — nor proves that `setDisplayName`'s "the response's echo wins, not the
116	/// locally-sent name" review patch actually survives a real backend-side
117	/// normalization.
118	///
119	/// Driven directly against `AccountSettingsRepository`'s own public API,
120	/// not through `tester.tap`/`pumpAndSettle`: each call awaits a genuine
121	/// async `dio` round trip, same rationale `dashboard_flow_e2e_test.dart`
122	/// already documents for its own cubits.
123	void main() {
124	  TestWidgetsFlutterBinding.ensureInitialized();
125	
126	  const secureStorageChannel = MethodChannel(
127	    'plugins.it_nomads.com/flutter_secure_storage',
128	  );
129	  final fakeNativeStorage = <String, String>{};
130	
131	  Future<dynamic> handleSecureStorageCall(MethodCall call) async {
132	    final args = call.arguments as Map<dynamic, dynamic>;
133	    switch (call.method) {
134	      case 'write':
135	        fakeNativeStorage[args['key'] as String] = args['value'] as String;
136	        return null;
137	      case 'read':
138	        return fakeNativeStorage[args['key'] as String];
139	      case 'delete':
140	        fakeNativeStorage.remove(args['key'] as String);
141	        return null;
142	      case 'containsKey':
143	        return fakeNativeStorage.containsKey(args['key'] as String);
144	      default:
145	        return null;
146	    }
147	  }
148	
149	  late FakePathProviderPlatform fakePathProvider;
150	  late _FakeHttpClientAdapter adapter;
151	
152	  setUp(() async {
153	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
154	        .setMockMethodCallHandler(
155	          secureStorageChannel,
156	          handleSecureStorageCall,
157	        );
158	    // setupCoreDependencies() also wires the entries feature, which opens a
159	    // Hive box (via Hive.initFlutter()) eagerly at registration time, not
160	    // lazily on first resolution — same rationale `dashboard_flow_e2e_test.
161	    // dart`'s own setUp already gives, even though this suite never touches
162	    // entries itself.
163	    fakePathProvider = FakePathProviderPlatform();
164	    PathProviderPlatform.instance = fakePathProvider;
165	
166	    await resetCoreDependencies();
167	    await setupCoreDependencies();
168	
169	    adapter = _FakeHttpClientAdapter();
170	    sl<Dio>().httpClientAdapter = adapter;
171	
172	    // account-settings-update is a bearer-required operation — seed a user
173	    // access token through the real AccessTokenProvider so the real header
174	    // interceptor has one to send.
175	    await sl<AccessTokenProvider>().saveAccessToken('e2e-test-access-token');
176	  });
177	
178	  tearDown(() async {
179	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
180	        .setMockMethodCallHandler(secureStorageChannel, null);
181	    fakeNativeStorage.clear();
182	    await Hive.close();
183	    await resetCoreDependencies();
184	    await fakePathProvider.cleanUp();
185	  });
186	
187	  test(
188	    'happy path: fetchBiometricEnabled() fires a genuine PATCH to '
189	    'account-settings-update with an empty body and real headers, decoding '
190	    'a real JSON payload into biometricEnabled/displayName/email '
191	    '(Boundaries: "called empty to read")',
192	    () async {
193	      adapter.queueJsonResponse(
194	        200,
195	        _settingsJson(
196	          biometricEnabled: false,
197	          displayName: 'Ana Silva',
198	          email: 'ana@example.com',
199	        ),
200	      );
201	
202	      final repository = sl<AccountSettingsRepository>();
203	      final result = await repository.fetchBiometricEnabled();
204	
205	      expect(result.isRight(), isTrue);
206	      expect(repository.currentBiometricEnabled, isFalse);
207	      expect(repository.currentDisplayName, 'Ana Silva');
208	      expect(repository.currentEmail, 'ana@example.com');
209	
210	      final request = adapter.requests.single;
211	      expect(request.path, sl<UrlBuilder>().build('account-settings-update'));
212	      expect(request.method, 'PATCH');
213	      expect(request.data, <String, dynamic>{});
214	      expect(request.headers['apikey'], dotenv.get('SUPABASE_ANON_KEY'));
215	      expect(request.headers['Authorization'], 'Bearer e2e-test-access-token');
216	    },
217	  );
218	
219	  test(
220	    'setBiometricEnabled(true) fires a genuine PATCH to '
221	    'account-settings-update with exactly {"biometricEnabled": true} and '
222	    'real headers',
223	    () async {
224	      adapter.queueJsonResponse(200, _settingsJson(biometricEnabled: true));
225	
226	      final repository = sl<AccountSettingsRepository>();
227	      final result = await repository.setBiometricEnabled(true);
228	
229	      expect(result.isRight(), isTrue);
230	      expect(repository.currentBiometricEnabled, isTrue);
231	
232	      final request = adapter.requests.single;
233	      expect(request.path, sl<UrlBuilder>().build('account-settings-update'));
234	      expect(request.data, {'biometricEnabled': true});
235	      expect(request.headers['apikey'], dotenv.get('SUPABASE_ANON_KEY'));
236	      expect(request.headers['Authorization'], 'Bearer e2e-test-access-token');
237	    },
238	  );
239	
240	  group('spec-8-3 — setDisplayName', () {
241	    test(
242	      'happy path: fires a genuine PATCH to account-settings-update with '
243	      'exactly {"displayName": name} and real headers, setting '
244	      'currentDisplayName from the real decoded response',
245	      () async {
246	        adapter.queueJsonResponse(
247	          200,
248	          _settingsJson(displayName: 'Ana Souza'),
249	        );
250	
251	        final repository = sl<AccountSettingsRepository>();
252	        final result = await repository.setDisplayName('Ana Souza');
253	
254	        expect(result.isRight(), isTrue);
255	        expect(repository.currentDisplayName, 'Ana Souza');
256	
257	        final request = adapter.requests.single;
258	        expect(
259	          request.path,
260	          sl<UrlBuilder>().build('account-settings-update'),
261	        );
262	        expect(request.data, {'displayName': 'Ana Souza'});
263	        expect(request.headers['apikey'], dotenv.get('SUPABASE_ANON_KEY'));
264	        expect(
265	          request.headers['Authorization'],
266	          'Bearer e2e-test-access-token',
267	        );
268	      },
269	    );
270	
271	    test(
272	      'code-review patch, proved for real: when the backend\'s own echoed '
273	      'displayName differs from the locally-sent name (e.g. server-side '
274	      'trimming/normalization), currentDisplayName takes the response\'s '
275	      'value, never the locally-sent one',
276	      () async {
277	        // Sends "  Ana Souza  " but the backend echoes back a normalized,
278	        // trimmed value — the real decode path, not a hand-written fake,
279	        // is what currentDisplayName must reflect.
280	        adapter.queueJsonResponse(
281	          200,
282	          _settingsJson(displayName: 'Ana Souza'),
283	        );
284	
285	        final repository = sl<AccountSettingsRepository>();
286	        await repository.setDisplayName('  Ana Souza  ');
287	
288	        expect(repository.currentDisplayName, 'Ana Souza');
289	      },
290	    );
291	
292	    test(
293	      'a non-retryable VALIDATION_ERROR (e.g. a name over the contract\'s '
294	      '80-char maxLength) maps through the real Failure.fromCode pipeline '
295	      'to a Left(Validation) — exactly one request left, no '
296	      'RetryInterceptor retry',
297	      () async {
298	        adapter.queueErrorResponse('VALIDATION_ERROR', 'nome muito longo');
299	
300	        final repository = sl<AccountSettingsRepository>();
301	        final result = await repository.setDisplayName('A' * 81);
302	
303	        expect(result.isLeft(), isTrue);
304	        result.match(
305	          (failure) => expect(failure, isA<Validation>()),
306	          (_) => fail('expected Left'),
307	        );
308	        expect(adapter.requests, hasLength(1));
309	      },
310	    );
311	
312	    test(
313	      'a retryable NETWORK_TIMEOUT exhausts the real RetryInterceptor\'s '
314	      'retries (1 + maxRetries requests, same policy the dashboard/export '
315	      'e2e suites already prove for their own functions) before surfacing '
316	      'as a Left',
317	      () async {
318	        for (var i = 0; i <= RetryInterceptor.maxRetries; i++) {
319	          adapter.queueErrorResponse('NETWORK_TIMEOUT', 'Tempo esgotado');
320	        }
321	
322	        final repository = sl<AccountSettingsRepository>();
323	        final result = await repository.setDisplayName('Ana Souza');
324	
325	        expect(result.isLeft(), isTrue);
326	        result.match(
327	          (failure) => expect(failure, isA<NetworkTimeout>()),
328	          (_) => fail('expected Left'),
329	        );
330	        expect(adapter.requests, hasLength(1 + RetryInterceptor.maxRetries));
331	      },
332	    );
333	
334	    test(
335	      'a response missing a required field (e.g. "email") maps through the '
336	      'real AccountRemoteDataSource try/catch and AccountSettingsDto\'s '
337	      'generated fromJson to a Left(MalformedResponse), never a crash — '
338	      'the local decode-failure path, not Failure.fromCode',
339	      () async {
340	        adapter.queueJsonResponse(200, {
341	          'data': {
342	            'id': 'u1',
343	            'displayName': 'Ana Souza',
344	            // 'email' deliberately omitted.
345	            'persona': 'empatico',
346	            'biometricEnabled': true,
347	            'serverRevision': 1,
348	            'createdAt': '2026-01-01T00:00:00Z',
349	            'updatedAt': '2026-01-01T00:00:00Z',
350	          },
351	        });
352	
353	        final repository = sl<AccountSettingsRepository>();
354	        final result = await repository.setDisplayName('Ana Souza');
355	
356	        expect(result.isLeft(), isTrue);
357	        result.match(
358	          (failure) => expect(failure, isA<MalformedResponse>()),
359	          (_) => fail('expected Left'),
360	        );
361	      },
362	    );
363	  });
364	
365	  // Story 8.4 — closes spec-8-4-logout.md's own deferred Review Finding:
366	  // "No real-DI (sl<...>-resolved) e2e test exists yet for the logout
367	  // orchestration end-to-end ... revisit there [this file] or as a
368	  // follow-up." The existing fakes-based router test
369	  // (`pumpWithLogoutFakesAndVaultGate` in `account_settings_screen_test.
370	  // dart`) already proves the lock-before-redirect widget-tree ordering;
371	  // this group instead drives the real `sl`-resolved `AccountSettingsCubit`
372	  // directly (same "call the public API, not tester.tap" rationale this
373	  // file's own doc gives), proving the genuine `auth-logout` POST, real
374	  // headers, and the real cross-repository cache-clear orchestration all
375	  // fire together.
376	  group('Story 8.4 — logout', () {
377	    test(
378	      'happy path: logout() locks the vault synchronously (before the '
379	      'queued backend response ever resolves), fires a genuine POST to '
380	      'auth-logout with real headers, clears the stored session, flips '
381	      'SessionStatus to unauthenticated, and empties both the entries '
382	      'and chat Hive boxes',
383	      () async {
384	        adapter.queueJsonResponse(200, {
385	          'data': {'ok': true},
386	        });
387	
388	        final vaultRepository = sl<VaultRepository>();
389	        final sessionRepository = sl<SessionRepository>();
390	        final entriesBox = sl<Box<Map>>();
391	        final chatSessionsBox = sl<Box<Map>>(
392	          instanceName: chatSessionsBoxName,
393	        );
394	        final chatMessagesBox = sl<Box<Map>>(
395	          instanceName: chatMessagesBoxName,
396	        );
397	
398	        // Seed the state logout must actually change: an unlocked vault,
399	        // an authenticated session, and non-empty caches in every box —
400	        // first-ever submitPin() unlocks unconditionally (VaultRepository
401	        // doc), markAuthenticated() is the same sync in-memory flip a real
402	        // login already triggers.
403	        await vaultRepository.submitPin('1234');
404	        sessionRepository.markAuthenticated();
405	        await entriesBox.put('e1', {'id': 'e1'});
406	        await chatSessionsBox.put('s1', {'id': 's1'});
407	        await chatMessagesBox.put('m1', {'id': 'm1'});
408	
409	        expect(vaultRepository.currentStatus, VaultStatus.unlocked);
410	        expect(sessionRepository.currentStatus, SessionStatus.authenticated);
411	
412	        final cubit = sl<AccountSettingsCubit>();
413	        final logoutFuture = cubit.logout();
414	
415	        // Boundaries: VaultRepository.lock() fires synchronously, BEFORE
416	        // the await on SessionRepository.logout() — true the instant
417	        // control returns here, before the queued network response has
418	        // had any chance to resolve.
419	        expect(vaultRepository.currentStatus, VaultStatus.locked);
420	
421	        await logoutFuture;
422	
423	        final request = adapter.requests.single;
424	        expect(request.path, sl<UrlBuilder>().build('auth-logout'));
425	        expect(request.method, 'POST');
426	        expect(request.headers['apikey'], dotenv.get('SUPABASE_ANON_KEY'));
427	        expect(
428	          request.headers['Authorization'],
429	          'Bearer e2e-test-access-token',
430	        );
431	
432	        expect(await sl<AccessTokenProvider>().readAccessToken(), isNull);
433	        expect(sessionRepository.currentStatus, SessionStatus.unauthenticated);
434	        expect(entriesBox.isEmpty, isTrue);
435	        expect(chatSessionsBox.isEmpty, isTrue);
436	        expect(chatMessagesBox.isEmpty, isTrue);
437	        expect(cubit.state.isLoggingOut, isFalse);
438	      },
439	    );
