      () async {
        adapter.queueJsonResponse(200, {
          'data': {'ok': true},
        });

        final cubit = sl<AccountSettingsCubit>();
        final first = cubit.deleteAccount();
        final second = cubit.deleteAccount();

        await Future.wait([first, second]);

        expect(adapter.requests, hasLength(1));
